package main

import (
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type EmpRec struct { // 01 EMP-REC, 17 bytes
	ErId    string          // PIC X(5) @0 len=5
	ErDept  string          // PIC X(3) @5 len=3
	ErHours decimal.Decimal // PIC 9(3)V9 @8 len=4
	ErRate  decimal.Decimal // PIC 9(3)V99 @12 len=5
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string // PIC X len=1 = "N"
var WsFirstFlag string // PIC X len=1 = "Y"
var WsPrevDept string // PIC X(3) len=3 = SPACES
var WsRegHours decimal.Decimal // PIC 9(3)V9 len=4 = 0
var WsOtHours decimal.Decimal // PIC 9(3)V9 len=4 = 0
var WsGross decimal.Decimal // PIC 9(7)V99 len=9 = 0
var WsDeptTotal decimal.Decimal // PIC 9(9)V99 len=11 = 0
var WsDeptCount int64 // PIC 9(3) len=3 = 0
var WsGrandTotal decimal.Decimal // PIC 9(11)V99 len=13 = 0
var WsGrandCount int64 // PIC 9(5) len=5 = 0
var WsHoursEd string // PIC ZZ9.9 len=5
var WsRateEd string // PIC ZZ9.99 len=6
var WsGrossEd string // PIC Z,ZZZ,ZZ9.99 len=12
var WsDeptEd string // PIC ZZZ,ZZZ,ZZ9.99 len=14
var WsGrandEd string // PIC ZZ,ZZZ,ZZZ,ZZ9.99 len=17

var curRec EmpRec
var empFileLines []string
var readIdx int

func isInputDone() bool { return WsEofFlag == "Y" }
func isFirstRecord() bool { return WsFirstFlag == "Y" }

func pow10Decimal(n int) decimal.Decimal {
	return decimal.New(1, int32(n))
}

func storeDecimal(val decimal.Decimal, intDigits int, scale int32, rounded bool) decimal.Decimal {
	var v decimal.Decimal
	if rounded {
		v = val.Round(scale)
	} else {
		v = val.Truncate(scale)
	}
	if intDigits == 0 && scale == 0 {
		return decimal.NewFromInt(0)
	}
	// keep low-order integer digits (mod 10^p)
	if intDigits > 0 {
		p10 := pow10Decimal(intDigits)
		intPart := v.Truncate(0)
		frac := v.Sub(intPart)
		// mod for positive and negative: decimal.Mod keeps sign of dividend
		mod := intPart.Mod(p10)
		v = mod.Add(frac)
		// Ensure scale still correct after mod (mod may lose trailing zeros but value is numeric)
		// Re-truncate/round already done, no need.
	}
	// Normalise to desired scale (keep trailing zeros conceptually, decimal equality holds)
	// Ensure the value is truncated to scale (already)
	return v
}

func storeInt(val int64, digits int) int64 {
	if digits <= 0 {
		return 0
	}
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	// low-order digits, keep sign? values are non-negative here
	// handle negative correctly
	r := val % mod
	if r < 0 {
		r += mod
	}
	return r
}

func formatEdited(val decimal.Decimal, picture string) string {
	// Find dot
	dotPos := strings.Index(picture, ".")
	var intPic, fracPic string
	if dotPos >= 0 {
		intPic = picture[:dotPos]
		fracPic = picture[dotPos+1:]
	} else {
		intPic = picture
		fracPic = ""
	}
	fracDigits := 0
	for _, c := range fracPic {
		if c == '9' || c == 'Z' {
			fracDigits++
		}
	}
	// int digit placeholders
	intDigitCount := 0
	for _, c := range intPic {
		if c == '9' || c == 'Z' {
			intDigitCount++
		}
	}

	// Get integer and fractional parts of val
	// Ensure val is at scale fracDigits (should be)
	// For safety truncate/round already.
	// Extract integer part low-order truncated already, but re-apply low-order for display if needed:
	// The display dropping high-order digits: we keep low-order intDigitCount digits.
	p10 := pow10Decimal(intDigitCount)
	intPart := val.Truncate(0)
	frac := val.Sub(intPart)
	// for negative values frac is negative; handle absolute for digit generation
	neg := val.Sign() < 0
	if neg {
		if intPart.Sign() < 0 {
			intPart = intPart.Neg()
		}
		if frac.Sign() < 0 {
			frac = frac.Neg()
		}
	}
	// keep low-order digits for display as well (if not already)
	if intDigitCount > 0 {
		intPart = intPart.Mod(p10)
		if intPart.Sign() < 0 {
			intPart = intPart.Add(p10)
		}
	}

	// Build integer digits string zero-padded to intDigitCount
	intStr := intPart.StringFixed(0) // no exponent
	// StringFixed may produce without leading zeros
	// Pad
	if len(intStr) < intDigitCount {
		intStr = strings.Repeat("0", intDigitCount-len(intStr)) + intStr
	} else if len(intStr) > intDigitCount {
		intStr = intStr[len(intStr)-intDigitCount:]
	}

	// Build fractional digits string
	fracStr := ""
	if fracDigits > 0 {
		// frac is e.g. 0.50 ; multiply by 10^fracDigits
		scalePow := pow10Decimal(fracDigits)
		fracScaled := frac.Mul(scalePow).Truncate(0)
		// Should be integer 0..10^f-1
		fs := fracScaled.StringFixed(0)
		if len(fs) < fracDigits {
			fs = strings.Repeat("0", fracDigits-len(fs)) + fs
		}
		fracStr = fs
	}

	// Map integer digits to placeholders
	// Collect placeholder indices for intPic
	type ph struct {
		pos int
		ch  rune
	}
	var placeholders []ph
	for i, c := range intPic {
		if c == '9' || c == 'Z' {
			placeholders = append(placeholders, ph{pos: i, ch: c})
		}
	}
	// Build rune slice for int part formatted
	intRunes := []rune(intPic)
	digitIdx := 0
	for _, p := range placeholders {
		// intStr indexes correspond to placeholders order
		d := rune(intStr[digitIdx])
		intRunes[p.pos] = d
		digitIdx++
	}
	// Now apply Z suppression
	// Determine significance: first non-zero digit among placeholders
	// Suppression applies to leading Z placeholders before significance
	significant := false
	// Find if there is any non-zero digit
	// We'll iterate placeholders in order; when we encounter non-zero, significant becomes true
	// However commas between placeholders need to be handled in second pass over intRunes
	// Approach: walk intRunes left to right, but need to know placeholder significance status at each point
	// Create map from pos to placeholder index
	posToPHIdx := make(map[int]int)
	for idx, p := range placeholders {
		posToPHIdx[p.pos] = idx
	}
	// Determine for each placeholder whether it is significant (should be digit not space)
	phSignificant := make([]bool, len(placeholders))
	for i, p := range placeholders {
		dch := intRunes[p.pos]
		if dch != '0' {
			// this and all following placeholders are significant
			for k := i; k < len(placeholders); k++ {
				phSignificant[k] = true
			}
			break
		} else {
			// zero; if this is a '9' mandatory, it is significant (prints zero)
			if p.ch == '9' {
				for k := i; k < len(placeholders); k++ {
					phSignificant[k] = true
				}
				break
			}
			// otherwise still not significant (will be space)
		}
	}
	// Edge: all zeros and no 9? but pictures have a 9 so covered. If all Zs and value zero, then nothing significant -> all spaces? But our pictures have 9.
	// Now build final int string with suppression
	for i, c := range intPic {
		if c == ',' {
			// comma is suppressed if no significant placeholder to its right has become significant before next significant?
			// Actually comma should be space until significance. Determine if there is any significant placeholder to the right that is significant and to the left significance not yet?
			// Simpler: comma is visible only if significance has been achieved at this point (i.e., there is a significant placeholder to the left) or there will be significant later but leading commas suppressed until first significant digit.
			// Check if any placeholder to the left is significant? Actually significance means we have passed first non-zero. So before that commas are spaces.
			// We can determine: find previous placeholder significance and next.
			// The rule: commas inside suppressed zone become spaces.
			// So comma is space if not yet significant.
			// Determine: look ahead/behind: if there exists a placeholder before this comma that is significant? Alternative: see if significant has started before this position.
			// Find the index of the next placeholder to the right: if the next placeholder that will be printed as digit (significant) hasn't arrived, comma suppressed.
			// Implement: check if there is at least one significant placeholder to the left that is already significant? Or simply if significant flag reached.
			// Compute whether we are in suppressed prefix: if no placeholder to the left is significant yet, suppress.
			// We can precompute prefix significance: has any placeholder up to previous become significant?
			isSuppressed := true
			// Find previous placeholder index
			prevIdx := -1
			for idx, p := range placeholders {
				if p.pos < i {
					prevIdx = idx
				}
			}
			// Find next placeholder index
			nextIdx := -1
			for idx, p := range placeholders {
				if p.pos > i {
					nextIdx = idx
					break
				}
			}
			// Suppressed if no significant placeholder on or before this comma? Actually once significance starts, commas after become visible.
			// Significance starts at first non-zero digit placeholder. So if prev placeholder that is significant exists, comma visible.
			// If significance hasn't started, comma is space.
			// Determine if significance has started before this comma: check if any placeholder <= prevIdx is significant and its digit is the start of significance (i.e., phSignificant and started)
			if prevIdx >= 0 {
				// if any placeholder up to prevIdx is the start, then significant has started
				// But phSignificant indicates whether this placeholder should be shown as digit (including zeros after start)
				// If phSignificant[prevIdx] is true, significance has started at or before prevIdx, so comma should be visible if there is also a significant placeholder to the right? But for numbers like 1,000 the comma should appear even though zeros after are significant due to earlier 1.
				// So we can check if there exists a significant placeholder at or before prev (i.e., phSignificant[prevIdx] true) then not suppressed? Actually if significance started earlier, all following placeholders are marked significant, so yes.
				if phSignificant[prevIdx] {
					isSuppressed = false
				}
			} else {
				// no placeholder before comma (leading comma) - suppress unless significance already (impossible)
				isSuppressed = true
			}
			// Also if there is no significant placeholder after? But should still be space if before significant
			_ = nextIdx
			if isSuppressed {
				intRunes[i] = ' '
			} else {
				intRunes[i] = ','
			}
		} else if c == 'Z' || c == '9' {
			phIdx := posToPHIdx[i]
			if !phSignificant[phIdx] {
				intRunes[i] = ' '
			} else {
				// keep digit already
			}
		} else {
			// should not happen
		}
	}
	intFormatted := string(intRunes)
	if dotPos >= 0 {
		return intFormatted + "." + fracStr
	}
	return intFormatted
}

func formatCount(val int64, digits int) string {
	mod := storeInt(val, digits)
	fmtStr := fmt.Sprintf("%%0%dd", digits)
	return fmt.Sprintf(fmtStr, mod)
}

// file helpers

func loadEmpFile() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			empFileLines = []string{}
			return
		}
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	// COBOL LINE SEQUENTIAL: split on lines, handle \r\n
	content := string(data)
	// Normalize CRLF to LF
	content = strings.ReplaceAll(content, "\r\n", "\n")
	content = strings.ReplaceAll(content, "\r", "\n")
	if content == "" {
		empFileLines = []string{}
		return
	}
	parts := strings.Split(content, "\n")
	// If file ends with newline, last part is empty trailing; COBOL would not have extra record.
	// Remove final empty part caused by trailing newline
	if len(parts) > 0 && parts[len(parts)-1] == "" {
		parts = parts[:len(parts)-1]
	}
	empFileLines = parts
}

func padLine(s string, length int) string {
	if len(s) >= length {
		return s[:length]
	}
	return s + strings.Repeat(" ", length-len(s))
}

func parseEmpRec(line string) EmpRec {
	line = padLine(line, 17)
	erId := line[0:5]
	erDept := line[5:8]
	sHours := line[8:12]
	sRate := line[12:17]
	hoursVal := parseDigits(sHours)
	rateVal := parseDigits(sRate)
	return EmpRec{
		ErId:    erId,
		ErDept:  erDept,
		ErHours: decimal.New(hoursVal, -1),
		ErRate:  decimal.New(rateVal, -2),
	}
}

func parseDigits(s string) int64 {
	t := strings.TrimSpace(s)
	if t == "" {
		return 0
	}
	// s may contain spaces? Filter digits
	// But spec says digits only
	var b strings.Builder
	for _, ch := range t {
		if ch >= '0' && ch <= '9' {
			b.WriteRune(ch)
		} else if ch == '-' {
			b.WriteRune(ch)
		}
	}
	if b.Len() == 0 {
		return 0
	}
	var v int64
	fmt.Sscan(b.String(), &v)
	return v
}

// Paragraphs

func MAIN_PARA() {
	// OPEN INPUT EMP-FILE
	loadEmpFile()
	readIdx = 0
	READ_PARA()
	for !isInputDone() {
		PROCESS_PARA()
	}
	if !isFirstRecord() {
		DEPT_BREAK_PARA()
	}
	// CLOSE EMP-FILE (no-op)
	GRAND_PARA()
}

func READ_PARA() {
	if readIdx >= len(empFileLines) {
		WsEofFlag = "Y"
		return
	}
	line := empFileLines[readIdx]
	readIdx++
	curRec = parseEmpRec(line)
}

func PROCESS_PARA() {
	if isFirstRecord() {
		WsPrevDept = curRec.ErDept
		WsFirstFlag = "N"
	} else {
		if curRec.ErDept != WsPrevDept {
			DEPT_BREAK_PARA()
			WsPrevDept = curRec.ErDept
		}
	}
	PAY_PARA()
	READ_PARA()
}

func PAY_PARA() {
	if curRec.ErHours.GreaterThan(decimal.NewFromInt(40)) {
		WsRegHours = storeDecimal(decimal.NewFromInt(40), 3, 1, false)
		diff := curRec.ErHours.Sub(decimal.NewFromInt(40))
		WsOtHours = storeDecimal(diff, 3, 1, false)
	} else {
		WsRegHours = storeDecimal(curRec.ErHours, 3, 1, false)
		WsOtHours = storeDecimal(decimal.NewFromInt(0), 3, 1, false)
	}
	onePointFive := decimal.NewFromInt(15).Shift(-1) // 1.5
	// WsRegHours * ErRate + WsOtHours * ErRate *1.5
	part1 := WsRegHours.Mul(curRec.ErRate)
	part2 := WsOtHours.Mul(curRec.ErRate).Mul(onePointFive)
	grossCalc := part1.Add(part2)
	WsGross = storeDecimal(grossCalc, 7, 2, true)

	WsDeptTotal = storeDecimal(WsDeptTotal.Add(WsGross), 9, 2, false)
	WsDeptCount = storeInt(WsDeptCount+1, 3)
	WsGrandTotal = storeDecimal(WsGrandTotal.Add(WsGross), 11, 2, false)
	WsGrandCount = storeInt(WsGrandCount+1, 5)

	WsHoursEd = formatEdited(storeDecimal(curRec.ErHours, 3, 1, false), "ZZ9.9")
	WsRateEd = formatEdited(storeDecimal(curRec.ErRate, 3, 2, false), "ZZ9.99")
	WsGrossEd = formatEdited(WsGross, "Z,ZZZ,ZZ9.99")

	// DISPLAY ER-ID " " ER-DEPT " " WS-HOURS-ED " " WS-RATE-ED " " WS-GROSS-ED.
	fmt.Println(curRec.ErId + " " + curRec.ErDept + " " + WsHoursEd + " " + WsRateEd + " " + WsGrossEd)
}

func DEPT_BREAK_PARA() {
	WsDeptEd = formatEdited(WsDeptTotal, "ZZZ,ZZZ,ZZ9.99")
	countStr := formatCount(WsDeptCount, 3)
	fmt.Println("  DEPT " + WsPrevDept + " EMPLOYEES: " + countStr + " TOTAL: " + WsDeptEd)
	WsDeptTotal = storeDecimal(decimal.NewFromInt(0), 9, 2, false)
	WsDeptCount = storeInt(0, 3)
}

func GRAND_PARA() {
	WsGrandEd = formatEdited(WsGrandTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	countStr := formatCount(WsGrandCount, 5)
	fmt.Println("GRAND TOTAL (" + countStr + "): " + WsGrandEd)
}

func main() {
	WsEofFlag = "N"
	WsFirstFlag = "Y"
	WsPrevDept = strings.Repeat(" ", 3)
	WsRegHours = decimal.NewFromInt(0)
	WsOtHours = decimal.NewFromInt(0)
	WsGross = decimal.NewFromInt(0)
	WsDeptTotal = decimal.NewFromInt(0)
	WsDeptCount = 0
	WsGrandTotal = decimal.NewFromInt(0)
	WsGrandCount = 0

	MAIN_PARA()
}

