func pow10Decimal(n int) decimal.Decimal {
	return decimal.New(1, int32(n))
}

func storeDecimal(val decimal.Decimal, intDigits int, scale int32, rounded bool) decimal.Decimal {
	var v decimal.Decimal
	if rounded {
		v = val.Round(scale)
	} else {
		v = val.Truncate(scale)
	}
	if intDigits == 0 && scale == 0 {
		return decimal.NewFromInt(0)
	}
	if intDigits > 0 {
		p10 := pow10Decimal(intDigits)
		intPart := v.Truncate(0)
		frac := v.Sub(intPart)
		mod := intPart.Mod(p10)
		v = mod.Add(frac)
	}
	return v
}

func storeInt(val int64, digits int) int64 {
	if digits <= 0 {
		return 0
	}
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	r := val % mod
	if r < 0 {
		r += mod
	}
	return r
}

func formatEdited(val decimal.Decimal, picture string) string {
	dotPos := strings.Index(picture, ".")
	var intPic, fracPic string
	if dotPos >= 0 {
		intPic = picture[:dotPos]
		fracPic = picture[dotPos+1:]
	} else {
		intPic = picture
		fracPic = ""
	}
	fracDigits := 0
	for _, c := range fracPic {
		if c == '9' || c == 'Z' {
			fracDigits++
		}
	}
	intDigitCount := 0
	for _, c := range intPic {
		if c == '9' || c == 'Z' {
			intDigitCount++
		}
	}

	p10 := pow10Decimal(intDigitCount)
	intPart := val.Truncate(0)
	frac := val.Sub(intPart)
	neg := val.Sign() < 0
	if neg {
		if intPart.Sign() < 0 {
			intPart = intPart.Neg()
		}
		if frac.Sign() < 0 {
			frac = frac.Neg()
		}
	}
	if intDigitCount > 0 {
		intPart = intPart.Mod(p10)
		if intPart.Sign() < 0 {
			intPart = intPart.Add(p10)
		}
	}

	intStr := intPart.StringFixed(0)
	if len(intStr) < intDigitCount {
		intStr = strings.Repeat("0", intDigitCount-len(intStr)) + intStr
	} else if len(intStr) > intDigitCount {
		intStr = intStr[len(intStr)-intDigitCount:]
	}

	fracStr := ""
	if fracDigits > 0 {
		scalePow := pow10Decimal(fracDigits)
		fracScaled := frac.Mul(scalePow).Truncate(0)
		fs := fracScaled.StringFixed(0)
		if len(fs) < fracDigits {
			fs = strings.Repeat("0", fracDigits-len(fs)) + fs
		}
		fracStr = fs
	}

	type ph struct {
		pos int
		ch  rune
	}
	var placeholders []ph
	for i, c := range intPic {
		if c == '9' || c == 'Z' {
			placeholders = append(placeholders, ph{pos: i, ch: c})
		}
	}
	intRunes := []rune(intPic)
	digitIdx := 0
	for _, p := range placeholders {
		d := rune(intStr[digitIdx])
		intRunes[p.pos] = d
		digitIdx++
	}
	posToPHIdx := make(map[int]int)
	for idx, p := range placeholders {
		posToPHIdx[p.pos] = idx
	}
	phSignificant := make([]bool, len(placeholders))
	for i, p := range placeholders {
		dch := intRunes[p.pos]
		if dch != '0' {
			for k := i; k < len(placeholders); k++ {
				phSignificant[k] = true
			}
			break
		} else {
			if p.ch == '9' {
				for k := i; k < len(placeholders); k++ {
					phSignificant[k] = true
				}
				break
			}
		}
	}
	for i, c := range intPic {
		if c == ',' {
			isSuppressed := true
			prevIdx := -1
			for idx, p := range placeholders {
				if p.pos < i {
					prevIdx = idx
				}
			}
			if prevIdx >= 0 {
				if phSignificant[prevIdx] {
					isSuppressed = false
				}
			} else {
				isSuppressed = true
			}
			if isSuppressed {
				intRunes[i] = ' '
			} else {
				intRunes[i] = ','
			}
		} else if c == 'Z' || c == '9' {
			phIdx := posToPHIdx[i]
			if !phSignificant[phIdx] {
				intRunes[i] = ' '
			}
		}
	}
	intFormatted := string(intRunes)
	if dotPos >= 0 {
		return intFormatted + "." + fracStr
	}
	return intFormatted
}

